extends CharacterBody2D

# --- SETTINGS ---
const SPEED = 150.0
const JUMP_VELOCITY = -400.0
const DOUBLE_JUMP_FORCE = -666.0 
const MAX_JUMPS = 3
const LAND_THRESHOLD = 0.9 

# BOREDOM RANDOM RANGE 🎲
const BOREDOM_MIN = 12.0
const BOREDOM_MAX = 22.0

# --- STATE VARIABLES ---
var jump_count = 0
var air_time = 0.0
var is_landing = false
var is_double_jumping = false

# BOREDOM STATES 🥱
var idle_timer = 0.0
var current_boredom_goal = 12.0
var is_deep_bored = false     # Variable for "Holding last frame"
var is_waking_up = false      # Variable for "Playing Undo animation"

@onready var sprite = $AnimatedSprite2D

func _ready():
	sprite.animation_finished.connect(_on_animation_finished)
	sprite.play("Idle")
	randomize_boredom() 

func _physics_process(delta: float) -> void:
	# 1. GRAVITY & AIR TIMER
	if not is_on_floor():
		velocity += get_gravity() * delta
		air_time += delta 
	else:
		jump_count = 0 

	# --- INPUT DETECTION ---
	# We check for input slightly differently now to handle the "Wake Up" phase.
	var input_direction = Input.get_axis("ui_left", "ui_right")
	var input_jump = Input.is_action_just_pressed("ui_accept")
	var is_trying_to_move = (input_direction != 0) or input_jump

	# --- BOREDOM INTERCEPTION ✋ ---
	# If we are trying to move, but we are stuck in Deep Boredom...
	if is_trying_to_move and is_deep_bored:
		# Trigger the wake up!
		start_waking_up()
		return # STOP HERE. Do not process movement. Do not collect $200.

	# If we are currently playing the "Undo" animation...
	if is_waking_up:
		return # STOP HERE. Wait for animation to finish.

	# --- NORMAL GAMEPLAY BELOW ---

	# 2. JUMP SYSTEM
	if input_jump and not is_landing:
		reset_boredom() 

		if is_on_floor():
			velocity.y = JUMP_VELOCITY
			sprite.play("AboutToJump")
			jump_count = 1 
		elif jump_count < MAX_JUMPS:
			velocity.y = DOUBLE_JUMP_FORCE
			jump_count += 1
			is_double_jumping = true 
			sprite.play("BoostedJump")
			is_landing = false 

	# 3. MOVEMENT INPUT
	if not is_landing:
		if input_direction:
			reset_boredom()

			velocity.x = input_direction * SPEED
			if input_direction < 0:
				sprite.flip_h = true
			else:
				sprite.flip_h = false

			if is_on_floor():
				sprite.play("Walk")
		else:
			# NOT MOVING? Count up! ⏱️
			if is_on_floor():
				idle_timer += delta 

				# If timer hits limit, start boredom sequence
				if idle_timer > current_boredom_goal and sprite.animation != "Bored1" and not is_deep_bored:
					sprite.play("Bored1")
					# Note: We become "Deep Bored" when this animation finishes (see below)

			velocity.x = move_toward(velocity.x, 0, SPEED)

			if is_on_floor() and sprite.animation != "StopWalk" and sprite.animation != "Idle" and sprite.animation != "Bored1":
				sprite.play("StopWalk")
	else:
		velocity.x = 0 

	# 4. AIR ANIMATIONS
	if not is_on_floor():
		is_landing = false 
		reset_boredom()

		if is_double_jumping:
			if velocity.y > -200 and sprite.animation == "BoostedJump":
				sprite.play("BoostedJumped")
		else:
			if velocity.y < -150:
				sprite.play("Jumped")
			elif velocity.y > -150 and velocity.y < 150:
				sprite.play("AboutToFall")
			elif velocity.y > 150:
				sprite.play("Falling")

	# 5. LANDING LOGIC
	var was_in_air = not is_on_floor()
	move_and_slide() 
	var is_on_floor_now = is_on_floor()

	if was_in_air and is_on_floor_now:
		is_double_jumping = false 
		if air_time > LAND_THRESHOLD:
			sprite.play("Landing")
			is_landing = true 
		else:
			sprite.play("Idle") 
		air_time = 0.0

# --- HELPER FUNCTIONS ---

func randomize_boredom():
	current_boredom_goal = randf_range(BOREDOM_MIN, BOREDOM_MAX)

func reset_boredom():
	idle_timer = 0.0
	is_deep_bored = false
	is_waking_up = false
	randomize_boredom() 

func start_waking_up():
	is_deep_bored = false
	is_waking_up = true
	sprite.play("Bored1 Undo")

func _on_animation_finished():
	if sprite.animation == "StopWalk":
		sprite.play("Idle")

	if sprite.animation == "Landing":
		is_landing = false
		sprite.play("Idle")

	if sprite.animation == "BoostedJumped":
		is_double_jumping = false 

	# BOREDOM LOGIC 🔗
	if sprite.animation == "Bored1":
		# Animation finished? LOCK IN.
		is_deep_bored = true
		# We do NOT play Idle. We just stay here. 🧊

	if sprite.animation == "Bored1 Undo":
		# Waking up finished? UNLOCK.
		is_waking_up = false
		reset_boredom()
		sprite.play("Idle")

